      "content": "import { expect, test } from 'bun:test';
import { DomainError, type UseCaseContext } from '@agentic-ddd/core';
import { covers, createTestContext } from '@agentic-ddd/testing';
import { CreateTask, createTaskOutput } from '../application/create-task';
import { TaskCreated } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

function setup() {
  const storage = new InMemoryTaskRepository();
  const calls: string[] = [];
  const repository: TaskRepository = {
    async findById(id) {
      calls.push(`load:${id}`);
      return storage.findById(id);
    },
    async save(task) {
      await storage.save(task);
      calls.push(`save:${task.id}`);
    },
  };
  const ctx = createTestContext({ correlationId: 'correlation-1', causationId: 'causation-1' });
  return { storage, calls, repository, ctx };
}

test(covers([
  'usecase:create_task',
  'criterion:0001/persistencia-criacao',
], 'salva t1 pendente, publica TaskCreated e rejeita repetição com TASK_ALREADY_EXISTS'), async () => {
  const fixture = setup();
  const ctx: UseCaseContext = {
    ...fixture.ctx,
    async publish(events) {
      expect(fixture.calls).toEqual(['load:t1', 'save:t1']);
      const stored = await fixture.storage.findById('t1');
      expect(stored?.title).toBe('Minha  tarefa');
      expect(stored?.status).toBe('pending');
      await fixture.ctx.publish(events);
      fixture.calls.push('publish');
    },
  };
  const useCase = new CreateTask(fixture.repository);
  expect(await fixture.storage.findById('t1')).toBeNull();

  const output = await useCase.execute({ task_id: 't1', title: ' \tMinha  tarefa\n ' }, ctx);

  expect(output).toEqual({ task_id: 't1', title: 'Minha  tarefa', status: 'pending' });
  expect(createTaskOutput.parse(output)).toEqual(output);
  expect(fixture.calls).toEqual(['load:t1', 'save:t1', 'publish']);
  expect(fixture.ctx.published).toHaveLength(1);
  expect(fixture.ctx.published[0]).toBeInstanceOf(TaskCreated);
  expect(fixture.ctx.published[0]?.payload).toEqual({ taskId: 't1', title: 'Minha  tarefa' });
  expect(fixture.ctx.published[0]?.correlationId).toBe(ctx.correlationId);
  expect(fixture.ctx.published[0]?.causationId).toBe(ctx.causationId);
  const stored = await fixture.storage.findById('t1');
  expect(stored?.pullEvents()).toEqual([]);

  const repetition = useCase.execute({ task_id: 't1', title: 'Outro título' }, ctx);

  await expect(repetition).rejects.toBeInstanceOf(DomainError);
  await expect(repetition).rejects.toHaveProperty('code', 'TASK_ALREADY_EXISTS');
  expect(fixture.calls).toEqual(['load:t1', 'save:t1', 'publish', 'load:t1']);
  expect(await fixture.storage.findById('t1')).toBe(stored);
  expect(stored?.title).toBe('Minha  tarefa');
  expect(stored?.status).toBe('pending');
  expect(fixture.ctx.published).toHaveLength(1);
});

test(covers([
  'usecase:create_task',
], 'rejeita título composto apenas por espaços sem salvar ou publicar'), async () => {
  const fixture = setup();
  const execution = new CreateTask(fixture.repository).execute({ task_id: 't1', title: ' \t\n ' }, fixture.ctx);

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toHaveProperty('code', 'TASK_TITLE_REQUIRED');
  expect(fixture.calls).toEqual(['load:t1']);
  expect(await fixture.storage.findById('t1')).toBeNull();
  expect(fixture.ctx.published).toEqual([]);
});

test(covers([
  'usecase:create_task',
], 'propaga falha ao salvar sem publicar TaskCreated'), async () => {
  const fixture = setup();
  const failure = new Error('Falha de persistência');
  const repository: TaskRepository = {
    findById: fixture.repository.findById,
    async save(task) {
      expect(task.id).toBe('t1');
      expect(task.status).toBe('pending');
      await Promise.resolve();
      throw failure;
    },
  };

  await expect(new CreateTask(repository).execute({ task_id: 't1', title: 'Tarefa' }, fixture.ctx)).rejects.toBe(failure);

  expect(fixture.calls).toEqual(['load:t1']);
  expect(await fixture.storage.findById('t1')).toBeNull();
  expect(fixture.ctx.published).toEqual([]);
});
